INSERT INTO public.learning_days (date, week_number, day_in_week, day_type, title, description, resources, deliverable, completed_override)
VALUES
  ('2026-08-18', 1, 1, 'study', 'Set up the toolkit', 'Install Python 3.11+, VS Code, and create a venv. Create the GitHub repository that will hold all projects and code throughout this 6-month journey.', '[{"label": "Python Official venv & Environment Guide", "url": "https://docs.python.org/3/tutorial/venv.html", "is_top_pick": true, "domain": "python.org"}, {"label": "VS Code Python Development Setup", "url": "https://code.visualstudio.com/docs/languages/python", "domain": "visualstudio.com"}, {"label": "Git & GitHub Repository Best Practices", "url": "https://docs.github.com/en/get-started", "domain": "github.com"}, {"label": "Modern Python Project Structure (Hypermodern)", "url": "https://cjolowicz.github.io/posts/hypermodern-python-01-setup/", "domain": "cjolowicz.github.io"}, {"label": "Real Python: Python 3.11 Features & Speedups", "url": "https://realpython.com/python311-new-features/", "domain": "realpython.com"}]'::jsonb, 'GitHub repository initialized with README and Python 3.11 virtual environment', NULL),
  ('2026-08-19', 1, 2, 'study', 'Learn async/await', 'Work through the official Python asyncio docs; write three small practice async functions demonstrating concurrent fetching, task gathering, and timeouts.', '[{"label": "Python asyncio Official Documentation", "url": "https://docs.python.org/3/library/asyncio.html", "is_top_pick": true, "domain": "python.org"}, {"label": "Real Python: Async IO in Python Complete Walkthrough", "url": "https://realpython.com/async-io-python/", "domain": "realpython.com"}, {"label": "HTTPX: Modern Async HTTP Client for Python", "url": "https://www.python-httpx.org/async/", "domain": "python-httpx.org"}, {"label": "Asyncio Event Loop & Coroutines Deep Dive", "url": "https://superfastpython.com/asyncio-event-loop/", "domain": "superfastpython.com"}, {"label": "GitHub: Python Asyncio Architecture Examples", "url": "https://github.com/timofurrer/awesome-asyncio", "domain": "github.com"}]'::jsonb, '3 functional asyncio scripts demonstrating concurrency patterns', NULL),
  ('2026-08-20', 1, 3, 'study', 'Learn Pydantic + type hints', 'Master Pydantic v2 data validation and strict typing. Model a complex sample API response as a Pydantic class with custom validators.', '[{"label": "Pydantic v2 Official Documentation & Migration", "url": "https://docs.pydantic.dev/latest/", "is_top_pick": true, "domain": "pydantic.dev"}, {"label": "FastAPI: Pydantic Schema Validation Patterns", "url": "https://fastapi.tiangolo.com/tutorial/body/", "domain": "tiangolo.com"}, {"label": "Real Python: Python Type Checking Guide", "url": "https://realpython.com/python-type-checking/", "domain": "realpython.com"}, {"label": "Towards Data Science: Modern Pydantic V2 Best Practices", "url": "https://towardsdatascience.com", "domain": "towardsdatascience.com"}, {"label": "GitHub: Pydantic Core & Data Models", "url": "https://github.com/pydantic/pydantic", "domain": "github.com"}]'::jsonb, 'Pydantic models with validation schemas for nested API payloads', NULL),
  ('2026-08-21', 1, 4, 'study', 'Build an Async CLI tool', 'Build an async command-line tool that concurrently calls a public REST API, parses and validates the JSON response with Pydantic, and outputs formatted results.', '[{"label": "Rich: Terminal Formatting & Live Progress", "url": "https://rich.readthedocs.io/en/latest/", "is_top_pick": true, "domain": "readthedocs.io"}, {"label": "Python HTTPX Async Client Guide", "url": "https://www.python-httpx.org/", "domain": "python-httpx.org"}, {"label": "Click: Python Composable CLI Framework", "url": "https://click.palletsprojects.com/", "domain": "palletsprojects.com"}, {"label": "Real Python: Beautiful Python CLIs", "url": "https://realpython.com/comparing-python-cli-libraries/", "domain": "realpython.com"}, {"label": "GitHub: Example Async REST CLI Repository", "url": "https://github.com/AlirezaNezami96", "domain": "github.com"}]'::jsonb, 'Working async CLI utility in Python with error handling', NULL),
  ('2026-08-22', 1, 5, 'study', 'Polish & commit', 'Clean up the CLI tool, write a concise and informative README with usage examples, and push the first verified commit of the roadmap.', '[{"label": "Conventional Commits Specification", "url": "https://www.conventionalcommits.org/en/v1.0.0/", "is_top_pick": true, "domain": "conventionalcommits.org"}, {"label": "Make a README: Standard Documentation Template", "url": "https://www.makeareadme.com/", "domain": "makeareadme.com"}, {"label": "Ruff: Ultra-Fast Python Linter and Formatter", "url": "https://docs.astral.sh/ruff/", "domain": "astral.sh"}, {"label": "GitHub Actions: Automated CI Testing Workflow", "url": "https://docs.github.com/en/actions", "domain": "github.com"}, {"label": "Real Python: Python Code Quality Tools", "url": "https://realpython.com/python-code-quality/", "domain": "realpython.com"}]'::jsonb, 'Cleaned repo with documentation and passing CLI tests', NULL),
