  ('2026-08-25', 2, 1, 'study', 'ChatGPT Prompt Engineering for Developers (Part 1)', 'Complete the first half of DeepLearning.AI''s ''ChatGPT Prompt Engineering for Developers'' taught by Andrew Ng and Isa Fulford.', '[{"label": "DeepLearning.AI: Prompt Engineering for Developers", "url": "https://www.deeplearning.ai/short-courses/chatgpt-prompt-engineering-for-developers/", "is_top_pick": true, "domain": "deeplearning.ai"}, {"label": "OpenAI: Official Prompt Engineering Best Practices", "url": "https://platform.openai.com/docs/guides/prompt-engineering", "domain": "openai.com"}, {"label": "Anthropic: Prompt Engineering Interactive Interactive Guide", "url": "https://docs.anthropic.com/en/docs/prompt-engineering", "domain": "anthropic.com"}, {"label": "LearnPrompting: Introductory LLM Guide", "url": "https://learnprompting.org/docs/intro", "domain": "learnprompting.org"}, {"label": "Weng Lil''Log: Prompt Engineering Overview", "url": "https://lilianweng.github.io/posts/2023-03-15-prompt-engineering/", "domain": "lilianweng.github.io"}]'::jsonb, 'Course notebook with prompting principles 1 & 2 exercises', NULL),
  ('2026-08-26', 2, 2, 'study', 'ChatGPT Prompt Engineering for Developers (Part 2)', 'Finish the course. Implement each technique (summarizing, inferring, transforming, expanding) in a standalone Jupyter notebook.', '[{"label": "DeepLearning.AI: Course Interactive Playground", "url": "https://www.deeplearning.ai/", "is_top_pick": true, "domain": "deeplearning.ai"}, {"label": "OpenAI Cookbook: Practical Prompting Patterns", "url": "https://cookbook.openai.com/", "domain": "openai.com"}, {"label": "JupyterLab Official Documentation", "url": "https://jupyterlab.readthedocs.io/", "domain": "readthedocs.io"}, {"label": "PromptingGuide.ai: Advanced Techniques Handbook", "url": "https://www.promptingguide.ai/", "domain": "promptingguide.ai"}, {"label": "GitHub: Prompt Engineering Interactive Exercises", "url": "https://github.com/dair-ai/Prompt-Engineering-Guide", "domain": "github.com"}]'::jsonb, 'Complete interactive Jupyter notebook covering all core prompting strategies', NULL),
  ('2026-08-27', 2, 3, 'study', 'Chip Huyen''s AI Engineering — Intro Chapter', 'Start Chip Huyen''s book ''AI Engineering'' (O''Reilly, 2025). Read the introduction chapter and explore the companion code repository.', '[{"label": "Chip Huyen: AI Engineering Book Companion Repository", "url": "https://github.com/chiphuyen/aie-book", "is_top_pick": true, "domain": "github.com"}, {"label": "Chip Huyen Official Blog & System Design Notes", "url": "https://huyenchip.com/", "domain": "huyenchip.com"}, {"label": "O''Reilly: AI Engineering Book Overview", "url": "https://www.oreilly.com/library/view/ai-engineering/9781098166298/", "domain": "oreilly.com"}, {"label": "Towards Data Science: Evolution of AI Engineering", "url": "https://towardsdatascience.com", "domain": "towardsdatascience.com"}, {"label": "Andrej Karpathy: State of GPT & LLM Paradigms", "url": "https://karpathy.ai/", "domain": "karpathy.ai"}]'::jsonb, 'Reading notes and environment setup for book companion code', NULL),
  ('2026-08-28', 2, 4, 'study', 'AI Engineering — Prompting Chapter', 'Continue Chip Huyen''s book, studying the in-depth prompting chapter. Analyze prompt optimization, token budgets, and prompt compression.', '[{"label": "Chip Huyen: AI Engineering Prompt Chapter Notes", "url": "https://huyenchip.com/blog/", "is_top_pick": true, "domain": "huyenchip.com"}, {"label": "OpenAI: Token Counting & Tokenizer Tool", "url": "https://platform.openai.com/tokenizer", "domain": "openai.com"}, {"label": "Tiktoken: Fast BPE Tokeniser for Python", "url": "https://github.com/openai/tiktoken", "domain": "github.com"}, {"label": "ArXiv: LLMLingua Prompt Compression Research", "url": "https://arxiv.org/abs/2310.05736", "domain": "arxiv.org"}, {"label": "Anthropic: Context Window Management Strategies", "url": "https://docs.anthropic.com/en/docs/context-window", "domain": "anthropic.com"}]'::jsonb, 'Summary of prompt engineering trade-offs and token optimization rules', NULL),
  ('2026-08-29', 2, 5, 'study', 'Prompting Strategy Comparison', 'Write a short benchmark comparison comparing few-shot vs. chain-of-thought (CoT) vs. structured-output prompting on a non-trivial classification/extraction task.', '[{"label": "ArXiv: Chain-of-Thought Prompting Research (Wei et al.)", "url": "https://arxiv.org/abs/2201.11903", "is_top_pick": true, "domain": "arxiv.org"}, {"label": "OpenAI: Structured Outputs Guide (JSON Mode & Pydantic)", "url": "https://platform.openai.com/docs/guides/structured-outputs", "domain": "openai.com"}, {"label": "Anthropic: Few-Shot Prompting Examples", "url": "https://docs.anthropic.com/en/docs/few-shot-prompting", "domain": "anthropic.com"}, {"label": "PromptingGuide.ai: Comparative Strategy Matrix", "url": "https://www.promptingguide.ai/techniques/cot", "domain": "promptingguide.ai"}, {"label": "GitHub: Structured Extraction Benchmark Code", "url": "https://github.com/AlirezaNezami96", "domain": "github.com"}]'::jsonb, 'Markdown report with sample prompts, outputs, and cost/accuracy comparison', NULL),
