  ('2026-09-01', 3, 1, 'study', 'Claude 101', 'Sign up at anthropic.skilljar.com; complete the ''Claude 101'' foundational course covering model capabilities, system prompts, and context windows.', '[{"label": "Anthropic Educational Academy (Skilljar)", "url": "https://anthropic.skilljar.com", "is_top_pick": true, "domain": "skilljar.com"}, {"label": "Anthropic Official Claude Documentation", "url": "https://docs.anthropic.com/en/home", "domain": "anthropic.com"}, {"label": "Simon Willison: Exploring Claude Model Generations", "url": "https://simonwillison.net/tags/claude/", "domain": "simonwillison.net"}, {"label": "DeepLearning.AI: Working with Claude Models", "url": "https://www.deeplearning.ai/", "domain": "deeplearning.ai"}, {"label": "GitHub: Anthropic Python Client SDK", "url": "https://github.com/anthropics/anthropic-sdk-python", "domain": "github.com"}]'::jsonb, 'Course completion badge & initial Anthropic SDK script', NULL),
  ('2026-09-02', 3, 2, 'study', 'Building with the Claude API — Auth & Requests', 'Work through ''Building with the Claude API'' modules on authentication, client setup, basic message requests, and parameter tuning (temperature, max_tokens).', '[{"label": "Anthropic: Messages API Reference", "url": "https://docs.anthropic.com/en/api/messages", "is_top_pick": true, "domain": "anthropic.com"}, {"label": "Anthropic Skilljar: Building with Claude API", "url": "https://anthropic.skilljar.com", "domain": "skilljar.com"}, {"label": "Python-dotenv: Secret & Environment Management", "url": "https://pypi.org/project/python-dotenv/", "domain": "pypi.org"}, {"label": "Real Python: Secure API Key Storage", "url": "https://realpython.com/python-api-keys/", "domain": "realpython.com"}, {"label": "GitHub: Anthropic Quickstart Templates", "url": "https://github.com/anthropics/anthropic-quickstarts", "domain": "github.com"}]'::jsonb, 'Python script with robust Anthropic client initialization and request wrappers', NULL),
  ('2026-09-03', 3, 3, 'study', 'Streaming & Tool Use Modules', 'Complete the streaming responses and tool use (function calling) modules in Anthropic Academy. Implement real-time SSE token streaming.', '[{"label": "Anthropic: Tool Use (Function Calling) Guide", "url": "https://docs.anthropic.com/en/docs/tool-use", "is_top_pick": true, "domain": "anthropic.com"}, {"label": "Anthropic: Streaming Messages API Guide", "url": "https://docs.anthropic.com/en/api/messages-streaming", "domain": "anthropic.com"}, {"label": "Mozilla Developer Network: Server-Sent Events (SSE)", "url": "https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events", "domain": "mozilla.org"}, {"label": "Rich: Live Streaming Console Display", "url": "https://rich.readthedocs.io/en/latest/live.html", "domain": "readthedocs.io"}, {"label": "GitHub: Anthropic Tool Use Examples", "url": "https://github.com/anthropics/anthropic-cookbook", "domain": "github.com"}]'::jsonb, 'Streaming terminal chat client using Claude API with JSON schema tool definitions', NULL),
  ('2026-09-04', 3, 4, 'study', 'Prompt Caching & Error Handling', 'Master Claude''s Prompt Caching to slash latency and cost by up to 90%. Implement exponential backoff, rate limit handling, and API error categorization.', '[{"label": "Anthropic: Prompt Caching Technical Guide", "url": "https://docs.anthropic.com/en/docs/prompt-caching", "is_top_pick": true, "domain": "anthropic.com"}, {"label": "Tenacity: Python Retrying & Backoff Library", "url": "https://tenacity.readthedocs.io/", "domain": "readthedocs.io"}, {"label": "Anthropic: Errors & Status Codes Reference", "url": "https://docs.anthropic.com/en/api/errors", "domain": "anthropic.com"}, {"label": "Towards Data Science: Cost Reduction with LLM Caching", "url": "https://towardsdatascience.com", "domain": "towardsdatascience.com"}, {"label": "GitHub: Prompt Caching Cost Benchmark Script", "url": "https://github.com/anthropics/anthropic-cookbook", "domain": "github.com"}]'::jsonb, 'Cached prompt pipeline with verified cache_read_input_tokens reduction', NULL),
  ('2026-09-05', 3, 5, 'study', 'Production Deployment Patterns', 'Study production deployment patterns module: secret management, latency optimizations, batch API requests, and monitoring token consumption.', '[{"label": "Anthropic: Production Readiness Checklist", "url": "https://docs.anthropic.com/en/docs/production-readiness", "is_top_pick": true, "domain": "anthropic.com"}, {"label": "Anthropic: Message Batches API Documentation", "url": "https://docs.anthropic.com/en/docs/batch-api", "domain": "anthropic.com"}, {"label": "12-Factor App: Config and Secrets Best Practices", "url": "https://12factor.net/config", "domain": "12factor.net"}, {"label": "Martin Fowler: Microservices and API Gateways", "url": "https://martinfowler.com/articles/gateway-pattern.html", "domain": "martinfowler.com"}, {"label": "GitHub: Claude Production Template Repository", "url": "https://github.com/AlirezaNezami96", "domain": "github.com"}]'::jsonb, 'Production-ready Claude client class with telemetry logging', NULL),
