  ('2026-09-09', 4, 2, 'study', 'Design Project #0: CLI Chatbot with Memory', 'Design Project #0 (CLI chatbot with structured conversation memory). Sketch the memory buffer architecture and message trimming strategy.', '[{"label": "Mermaid.js: Dynamic Architecture Diagramming", "url": "https://mermaid.js.org/", "is_top_pick": true, "domain": "mermaid.js.org"}, {"label": "LangChain: Conversation Memory Buffer Concepts", "url": "https://python.langchain.com/docs/how_to/memory_chat_history/", "domain": "langchain.com"}, {"label": "Anthropic: Managing Multi-Turn Conversational State", "url": "https://docs.anthropic.com/en/docs/system-prompts", "domain": "anthropic.com"}, {"label": "Towards Data Science: Stateful LLM Applications", "url": "https://towardsdatascience.com", "domain": "towardsdatascience.com"}, {"label": "GitHub: Project #0 Design Architecture Spec", "url": "https://github.com/AlirezaNezami96", "domain": "github.com"}]'::jsonb, 'Architecture diagram and technical specification document', NULL),
  ('2026-09-10', 4, 3, 'study', 'Build Core Chat Loop & Memory Buffer', 'Build the core conversational loop in Python. Implement sliding-window memory with token counting to maintain context without overflowing limits.', '[{"label": "Anthropic SDK: Complete Python Client Reference", "url": "https://github.com/anthropics/anthropic-sdk-python", "is_top_pick": true, "domain": "github.com"}, {"label": "Tiktoken Token Counter for Token Budgeting", "url": "https://pypi.org/project/tiktoken/", "domain": "pypi.org"}, {"label": "Python SQLite3: Local Session Persistence", "url": "https://docs.python.org/3/library/sqlite3.html", "domain": "python.org"}, {"label": "Real Python: Building Terminal User Interfaces", "url": "https://realpython.com/python-gui-curses/", "domain": "realpython.com"}, {"label": "Rich: Layout & Panel Terminal Rendering", "url": "https://rich.readthedocs.io/en/stable/layout.html", "domain": "readthedocs.io"}]'::jsonb, 'Working stateful chat engine with memory persistence across sessions', NULL),
