  ('2026-09-15', 5, 1, 'study', 'Understanding & Applying Text Embeddings', 'Complete DeepLearning.AI''s ''Understanding and Applying Text Embeddings''. Study vector spaces, cosine similarity, and semantic search fundamentals.', '[{"label": "DeepLearning.AI: Text Embeddings Course", "url": "https://www.deeplearning.ai/short-courses/google-cloud-vertex-ai/", "is_top_pick": true, "domain": "deeplearning.ai"}, {"label": "Pinecone: Vector Embeddings Explained for Beginners", "url": "https://www.pinecone.io/learn/vector-embeddings/", "domain": "pinecone.io"}, {"label": "OpenAI: Embeddings API & Text Similarity Guide", "url": "https://platform.openai.com/docs/guides/embeddings", "domain": "openai.com"}, {"label": "Hugging Face: MTEB Massive Text Embedding Benchmark", "url": "https://huggingface.co/spaces/mteb/leaderboard", "domain": "huggingface.co"}, {"label": "Scikit-Learn: Cosine Similarity & Vector Metrics", "url": "https://scikit-learn.org/stable/modules/generated/sklearn.metrics.pairwise.cosine_similarity.html", "domain": "scikit-learn.org"}]'::jsonb, 'Cosine similarity calculator and embedding visualization script', NULL),
  ('2026-09-16', 5, 2, 'study', 'Vector Databases: From Embeddings to Applications (Part 1)', 'Work through the first half of DeepLearning.AI''s ''Vector Databases: from Embeddings to Applications'' covering ANN algorithms (HNSW, IVF).', '[{"label": "DeepLearning.AI: Vector Databases Short Course", "url": "https://www.deeplearning.ai/short-courses/vector-databases-embeddings-applications/", "is_top_pick": true, "domain": "deeplearning.ai"}, {"label": "Pinecone: Hierarchical Navigable Small World (HNSW) Explained", "url": "https://www.pinecone.io/learn/series/faiss/hnsw/", "domain": "pinecone.io"}, {"label": "Qdrant: Vector Search Indexing Concepts", "url": "https://qdrant.tech/documentation/concepts/indexing/", "domain": "qdrant.tech"}, {"label": "ArXiv: Efficient & Robust Approximate Nearest Neighbor Search (Malkov et al.)", "url": "https://arxiv.org/abs/1603.09320", "domain": "arxiv.org"}, {"label": "Towards Data Science: How Vector Search Actually Works", "url": "https://towardsdatascience.com", "domain": "towardsdatascience.com"}]'::jsonb, 'Notes on HNSW graph indexing vs Flat search complexity', NULL),
  ('2026-09-17', 5, 3, 'study', 'Vector Databases (Part 2)', 'Finish the vector database course. Practice filtered search, metadata payload indexing, and multi-tenant namespace isolation.', '[{"label": "Qdrant: Payload Filtering & Namespaces Guide", "url": "https://qdrant.tech/documentation/concepts/filtering/", "is_top_pick": true, "domain": "qdrant.tech"}, {"label": "Chroma DB: Metadata Filtering & Collections", "url": "https://docs.trychroma.com/usage-guide#filtering-by-metadata", "domain": "trychroma.com"}, {"label": "DeepLearning.AI: Multi-Tenant Vector DB Pipelines", "url": "https://www.deeplearning.ai/", "domain": "deeplearning.ai"}, {"label": "Pinecone: Metadata Filtering Best Practices", "url": "https://docs.pinecone.io/guides/data/filter-with-metadata", "domain": "pinecone.io"}, {"label": "GitHub: Vector Search Metadata Filtering Sandbox", "url": "https://github.com/AlirezaNezami96", "domain": "github.com"}]'::jsonb, 'Course completion exercises and benchmark comparisons', NULL),
  ('2026-09-18', 5, 4, 'study', 'Set up Local Qdrant / Chroma', 'Install and run Qdrant or Chroma locally via Docker or in-memory Python client. Index a small test dataset and execute top-k semantic similarity queries.', '[{"label": "Chroma DB Official Quickstart & Python Setup", "url": "https://docs.trychroma.com/getting-started", "is_top_pick": true, "domain": "trychroma.com"}, {"label": "Qdrant: Docker Quickstart & Local Installation", "url": "https://qdrant.tech/documentation/quickstart/", "domain": "qdrant.tech"}, {"label": "Docker: Running Database Containers Locally", "url": "https://docs.docker.com/engine/reference/run/", "domain": "docker.com"}, {"label": "FastEmbed: Fast Lightweight Local Embedding Generation", "url": "https://github.com/qdrant/fastembed", "domain": "github.com"}, {"label": "Real Python: Working with Docker in Python", "url": "https://realpython.com/python-docker/", "domain": "realpython.com"}]'::jsonb, 'Local vector store instance running with automated collection initialization', NULL),
